package candle

import "math"

// The expected values were recorded from the Java API (QD 3.356) and are shared with the C++ API tests.
// Generated from the C++ table, do not edit by hand.

type periodParseCase struct {
	input    string
	ok       bool
	value    float64
	typeName string
	str      string
	millis   int64
}

type periodValueOfCase struct {
	value    float64
	typeName string
	str      string
	millis   int64
}

type typeParseCase struct {
	input    string
	typeName string // empty: parse must fail
}

type priceLevelParseCase struct {
	input     string
	ok        bool
	str       string
	isDefault bool
}

type priceLevelValueOfCase struct {
	value float64
	str   string // empty: the value must be rejected
}

type symbolCase struct {
	input      string
	ok         bool
	str        string // Java toString(); Java keeps the default attributes
	base       string
	price      string
	session    string
	period     string
	alignment  string
	priceLevel string
}

